{
 "cases": [
  {
   "i": 9795,
   "title": "Analytics dashboard access issues",
   "description": "Users are getting locked out of the analytics dashboard in the EU staging environment. We have about 29 people trying to get in and they can't. It's been happening for a while now. Please look into it."
  },
  {
   "i": 9796,
   "title": "Payment Gateway v2: Overcharges, Missing Refunds, and Renewal Failures in Production",
   "description": "We are experiencing multiple billing issues with Payment Gateway v2 in the US-East production environment since yesterday afternoon. \n\n1. Several customers report being overcharged for their subscriptions.\n2. Refunds issued through the admin panel are not reflecting on customer statements or bank accounts.\n3. Subscription renewals are failing, leaving active accounts in a suspended state despite valid payment methods.\n\nApproximately 42 users are currently affected, and this is causing moderate disruption to our billing operations. Please investigate these specific transaction types."
  },
  {
   "i": 9797,
   "title": "Status Page UI Glitches: Blank Screen, Missing Localization, and Broken Filters",
   "description": "We have identified three distinct issues on the Status Page in the US-West production environment. \n\n1. A blank screen appears when accessing the main dashboard view for some users.\n2. Localization text is missing, showing default keys instead of translated strings for non-English users.\n3. Sorting and filtering options are unresponsive or returning incorrect results.\n\nAlthough these are visual and functional bugs, no actual business impact or affected users have been reported at this time. We would like these fixed for UI consistency."
  },
  {
   "i": 9798,
   "title": "Config Manager: Service Returns 503 and Failover Not Triggering",
   "description": "The Config Manager service in the APAC production region is returning HTTP 503 errors. Additionally, the failover mechanism does not appear to be kicking in when the primary endpoint goes down, leaving the service unavailable for approximately 32 users. This is causing moderate business impact as configuration updates are blocked. Please check the health checks and failover logic."
  },
  {
   "i": 9799,
   "title": "Deploy Manager: Service Unresponsive and Pods Restarting in ANZ",
   "description": "We are seeing instances of the Deploy Manager in the ANZ production environment becoming unresponsive. A partial outage was reported, and we observe that the associated pods are restarting repeatedly. Currently, there are no reported business impacts or affected users, but we want to address this instability before it causes wider issues. Please investigate the pod restart loop and service availability."
  },
  {
   "i": 9800,
   "title": "Critical: SSO Integration Module Rate Limiting and Timeouts in Staging",
   "description": "The SSO Integration Module in the APAC staging environment is failing to authenticate users due to rate limit exceeded errors (HTTP 429) and subsequent timeouts. This issue is impacting 1480 users and is blocking our entire testing pipeline, resulting in a critical business impact. Please review the rate limiting configuration and timeout settings immediately."
  },
  {
   "i": 9801,
   "title": "Customer Portal White Screen/Blank Page Issue",
   "description": "Users in the US-West production environment are encountering a white screen of death when accessing the Customer Portal. About 497 users are affected, and this is having a high impact on our customer support operations. We think this is definitely a policy misconfiguration causing the portal to fail to load content. Please review the access policies."
  },
  {
   "i": 9802,
   "title": "Payment Gateway v2 Declining Payments and Triggering Chargebacks",
   "description": "We are seeing a high volume of declined payments through the Payment Gateway v2 in the US-West staging environment. Furthermore, we have received multiple chargeback notices for transactions that should have been successful or handled differently. This is critically impacting 1235 users. We believe the issue lies within the Payment Gateway logic itself, as it seems to be incorrectly processing valid card details."
  },
  {
   "i": 9803,
   "title": "API Gateway: Upstream Dependency Errors and Third-Party Unavailability",
   "description": "The API Gateway in the US-West production environment is throwing errors related to third-party API unavailability and upstream dependency failures. This is affecting 496 users and causing a high business impact as external integrations are broken. Please investigate the connection to the upstream services and the error handling within the gateway."
  },
  {
   "i": 9804,
   "title": "Payment Gateway v2: Billing Discrepancies (Undercharges, Incorrect Invoices, Non-Renewals)",
   "description": "In the LATAM production environment, we are observing irregularities with Payment Gateway v2. Some subscriptions are not renewing, others are being undercharged, and invoices are appearing incorrect. Since these symptoms involve both charging and invoice generation, we are unsure if the root cause is within the gateway's processing logic or potentially related to the refund or billing services it interacts with. Approximately 68 users are affected with moderate impact."
  },
  {
   "i": 9805,
   "title": "Billing Engine: Incorrect Invoices Generated",
   "description": "The Billing Engine in the LATAM production environment is generating incorrect invoices for 17 users. This is causing moderate business impact as customers are receiving wrong amounts. We are confident the issue is within the Billing Engine's calculation logic or data retrieval, as the input data appears correct on our end. Please investigate the invoice generation process."
  },
  {
   "i": 9806,
   "title": "Currency Converter Issues: Refunds Not Reflecting and Double Charges",
   "description": "We are seeing issues attributed to the Currency Converter in the EU-Central production environment. Specifically, refunds are not being reflected correctly after conversion, and some users are being charged twice for the same transaction. This is affecting 8 users with low business impact. Please check the conversion logic and transaction handling within the Currency Converter."
  },
  {
   "i": 9807,
   "title": "OAuth Service: Data Residency Mismatch and Missing Audit Logs",
   "description": "The OAuth Service in the LATAM development environment is showing data residency flag mismatches and failing to log certain entry types in the audit logs. This is affecting 70 developers/testers and causing moderate impact on our compliance testing. We believe these issues stem from the OAuth Service's internal data handling and logging mechanisms."
  },
  {
   "i": 9808,
   "title": "Data Pipeline: Intermittent Failures and Slow Responses",
   "description": "We are experiencing intermittent failures and slow response times with the Data Pipeline in the LATAM staging environment. This is affecting 43 users with moderate impact. Because the pipeline relies on external triggers, we cannot definitively say if the latency is in the data processing itself or if the webhook dispatch service is failing to signal completion properly. Both areas need investigation to isolate the bottleneck."
  },
  {
   "i": 9809,
   "title": "OAuth Service: Webhooks Not Firing and API Schema Errors",
   "description": "The OAuth Service in the EU-West staging environment is failing to fire webhooks and is returning API schema errors during token exchanges. This is affecting 13 users with moderate impact. We think the OAuth Service is not correctly validating the webhook payloads or the API response structure, causing the integration to break."
  }
 ]
